ALTER TABLE "Variant" ADD CONSTRAINT "Variant_nonnegative" CHECK (stock >= 0 AND "averageCost" >= 0);
ALTER TABLE "Product" ADD CONSTRAINT "Product_nonnegative" CHECK (price >= 0 AND "onlinePrice" >= 0 AND cost >= 0 AND threshold >= 0);
ALTER TABLE "Order" ADD CONSTRAINT "Order_nonnegative" CHECK (total >= 0 AND tax >= 0 AND shipping >= 0 AND discount >= 0 AND cost >= 0);
ALTER TABLE "OrderLine" ADD CONSTRAINT "OrderLine_quantities" CHECK (quantity > 0 AND returned >= 0 AND returned <= quantity AND net >= 0 AND discount >= 0);
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_positive" CHECK (amount > 0);
ALTER TABLE "Purchase" ADD CONSTRAINT "Purchase_balance" CHECK (total >= 0 AND paid >= 0 AND paid <= total);
ALTER TABLE "PurchaseLine" ADD CONSTRAINT "PurchaseLine_positive" CHECK (quantity > 0 AND cost >= 0);
ALTER TABLE "GiftCard" ADD CONSTRAINT "GiftCard_nonnegative" CHECK (balance >= 0 AND issued >= 0);
ALTER TABLE "Customer" ADD CONSTRAINT "Customer_credit_nonnegative" CHECK (credit >= 0);
ALTER TABLE "JournalLine" ADD CONSTRAINT "JournalLine_one_side" CHECK (debit >= 0 AND credit >= 0 AND NOT (debit > 0 AND credit > 0));
CREATE UNIQUE INDEX "Drawer_one_open_session" ON "Drawer" ((true)) WHERE "closedAt" IS NULL;
